async function countHarvests(excel) {
  const sheet = excel.workbook.worksheets.getItem("Harvests")
  const usedRange = sheet.getUsedRange()
  usedRange.load("values")
  await excel.sync()
  const harvestCount = usedRange.values.length - 1
  Jade.print(`There are ${harvestCount} harvests.`, "Harvest count")
  Jade.open_output()
}
